def min_coins_needed(coins, b):
    from collections import Counter
    import math

    # Count the occurrences of each coin value
    coin_count = Counter(coins)

    # If b is not a power of 2, it's impossible to form
    if b & (b - 1) != 0:
        return -1

    # Initialize the number of coins needed
    num_coins = 0

    # Iterate over powers of 2 from the largest to the smallest
    current_power = 1
    while b > 0:
        if b & current_power:
            if coin_count[current_power] > 0:
                coin_count[current_power] -= 1
            else:
                # If we don't have this power of 2, we need to find a combination
                power_of_2 = current_power
                while power_of_2 < b:
                    power_of_2 <<= 1
                if power_of_2 > b:
                    power_of_2 >>= 1
                while power_of_2 > 0:
                    if b & power_of_2 and coin_count[power_of_2] > 0:
                        b -= power_of_2
                        coin_count[power_of_2] -= 1
                        num_coins += 1
                    power_of_2 >>= 1
                if b > 0:
                    return -1
        current_power <<= 1

    return num_coins

